import type { ReactNode } from "react";

interface FieldProps {
  id: string;
  label: string;
  optional?: string;
  /** `null`: контрола с id нет (ошибка загрузки тренеров), метка выводится без `for`. */
  labelFor?: string | null;
  hint?: string;
  counter?: string;
  error?: string;
  children: ReactNode;
}

interface AriaOptions {
  hint?: boolean;
  counter?: boolean;
  error?: boolean;
  /** Дополнительные id описаний (общая ошибка пары Date/Start time, единица измерения). */
  extra?: readonly string[];
  /** По умолчанию равно `error`. */
  invalid?: boolean;
}

/** `aria-invalid` и `aria-describedby` для контрола поля `id`; id описаний совпадают с `Field`. */
export function ariaFor(id: string, options: AriaOptions = {}) {
  const ids: string[] = [];
  if (options.hint) ids.push(`${id}-hint`);
  if (options.counter) ids.push(`${id}-counter`);
  if (options.extra) ids.push(...options.extra);
  if (options.error) ids.push(`${id}-error`);
  const invalid = options.invalid ?? options.error ?? false;
  return {
    "aria-invalid": invalid ? (true as const) : undefined,
    "aria-describedby": ids.length > 0 ? ids.join(" ") : undefined,
  };
}

export function FieldError({ id, children }: { id: string; children: ReactNode }) {
  return (
    <p id={id} className="field-error">
      <span aria-hidden="true">! </span>
      {children}
    </p>
  );
}

/** Метка, контрол, подсказка, счётчик и ошибка поля. Контрол получает `ariaFor` от вызывающего. */
export function Field({ id, label, optional, labelFor, hint, counter, error, children }: FieldProps) {
  const target = labelFor === undefined ? id : labelFor;
  return (
    <div className="field">
      {target === null ? (
        <span className="field-label">{label}</span>
      ) : (
        <label className="field-label" htmlFor={target}>
          {label}
          {optional ? <span className="field-optional"> {optional}</span> : null}
        </label>
      )}
